//   - name: "Validates and transforms with Zod"
//     options:
//       command: 'npx tsx --no-cache --tsconfig ./tsconfig.json zod.ts hello --name sir'
//     assertions:
//       stdout:
//         matches: 'Hello, SIR!.*sssssnake_case: sir'
