    properties: {
      prs: {
        type: 'oneOf',
        description:
          'Filter by PR count — a shorthand like ">5" or structured min/max',
        valueTypes: [
          {
            type: 'object',
            properties: {
              min: { type: 'number' },
              max: { type: 'number' },
            },
          },
          { type: 'string' },
        ],
      } as any,
      stars: {
        type: 'oneOf',
        description:
          'Filter by star count — a shorthand like ">=100" or structured min/max',
        valueTypes: [
          {
            type: 'object',
            properties: {
              min: { type: 'number' },
              max: { type: 'number' },
            },
          },
          { type: 'string' },
        ],
      } as any,
    },
  })
  .handler((args) => {
    const parts: string[] = [];
    if (args.filter?.prs !== undefined) {
